let worlds=[],page=0;const el=id=>document.getElementById(id);function render(){const q=el('search').value.toLowerCase(),f=el('family').value,list=worlds.filter(t=>(!f||t.family===f)&&t.name.toLowerCase().includes(q));page=Math.max(0,Math.min(page,Math.ceil(list.length/24)-1));el('worlds').replaceChildren();for(const t of list.slice(page*24,page*24+24)){const a=document.createElement('article'),img=document.createElement('img'),h=document.createElement('h2'),small=document.createElement('small'),p=document.createElement('p'),dl=document.createElement('dl');img.src='/assets/planets/'+t.id+'.svg';img.alt=t.name;img.loading='lazy';h.textContent=t.name;small.textContent=t.rarity+' · '+t.family+' · '+(t.uniquePerRound?'Once per round':'Environment type');p.textContent=t.lore;for(const [k,v] of [['Habitability',t.habitability+'%'],['Biodiversity',t.biodiversity+'%'],['Moisture',t.moisture+'%'],['Rockiness',t.rockiness+'%'],['Founding population',t.basePopulation],['Growth',t.growthPercent+'%'],['Travel ETA',(t.travelEtaBonus||0)+' tick'],['Bonus salvage',(t.salvageBonusPercent||0)+'%']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;dl.append(dt,dd);}a.append(img,small,h,dl,p);el('worlds').append(a);}el('count').textContent=list.length+' worlds · page '+(page+1)+' / '+Math.max(1,Math.ceil(list.length/24));el('prev').disabled=page===0;el('next').disabled=(page+1)*24>=list.length;}for(const id of ['search','family'])el(id).oninput=()=>{page=0;render();};el('prev').onclick=()=>{page--;render();};el('next').onclick=()=>{page++;render();};fetch('/planet-catalog.json').then(r=>r.json()).then(d=>{worlds=d;render();});